require_once __DIR__.'/app/bootstrap.php';require_login();$pdo=db_connect();$id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT * FROM t_qc_attachment WHERE id=?');$st->execute([$id]);$f=$st->fetch();if(!$f){http_response_code(404);exit('File not found.');}$base=realpath(__DIR__.'/uploads');$path=realpath(__DIR__.'/uploads/'.$f['stored_name']);if(!$base||!$path||strpos($path,$base)!==0||!is_file($path)){http_response_code(404);exit('Stored file not found.');}header('Content-Type: '.$f['mime_type']);header('Content-Length: '.filesize($path));header('Content-Disposition: inline; filename="'.rawurlencode($f['original_name']).'"');readfile($path);exit;
